START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261017070452_AddLiveStreams') THEN
    CREATE TABLE "LiveStreams" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CompetitionId" integer NOT NULL,
        "ArenaName" character varying(80) NOT NULL,
        "AngleName" character varying(60) NOT NULL,
        "Status" integer NOT NULL,
        "Caption" character varying(80),
        "AudioMuted" boolean NOT NULL,
        "HasAudio" boolean NOT NULL,
        "Simulcast" boolean NOT NULL,
        "StartedByUserId" text NOT NULL,
        "StartedAt" timestamp with time zone NOT NULL,
        "LastHeartbeatAt" timestamp with time zone NOT NULL,
        "EndedAt" timestamp with time zone,
        "SfuSessionId" character varying(100),
        "Generation" integer NOT NULL,
        "PendingSfuSessionId" character varying(100),
        "PendingAttempt" integer,
        "PendingHasAudio" boolean NOT NULL,
        "PendingSimulcast" boolean NOT NULL,
        "PendingSince" timestamp with time zone,
        "TakeOverStreamId" integer,
        "SfuTrackMids" text NOT NULL,
        "PendingTrackMids" text NOT NULL,
        CONSTRAINT "PK_LiveStreams" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_LiveStreams_Competitions_CompetitionId" FOREIGN KEY ("CompetitionId") REFERENCES "Competitions" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261017070452_AddLiveStreams') THEN
    CREATE INDEX "IX_LiveStreams_CompetitionId_Status" ON "LiveStreams" ("CompetitionId", "Status");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261017070452_AddLiveStreams') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261017070452_AddLiveStreams', '10.0.8');
    END IF;
END $EF$;
COMMIT;

